import hmac
import os
import time

import structlog
from flask import Blueprint, request

from src.api import errors
from src.jobs import queue

bp = Blueprint("webhooks", __name__)
log = structlog.get_logger()

MAX_EVENT_AGE_SECONDS = 300


def _verify_signature():
    """Check the PSP signature and timestamp; return True if the event is authentic."""
    secret = os.environ["PSP_WEBHOOK_SECRET"].encode()
    signature = request.headers.get("Psp-Signature", "")
    timestamp = request.headers.get("Psp-Timestamp", "")

    expected = hmac.new(secret, request.get_data(), hashlib.sha256).hexdigest()
    if not hmac.compare_digest(expected, signature):
        return False

    try:
        age = abs(time.time() - int(timestamp))
    except ValueError:
        return False
    return age <= MAX_EVENT_AGE_SECONDS


@bp.post("/webhooks/psp")
def psp_webhook():
    if not _verify_signature():
        return errors.problem(401, "Invalid webhook signature")

    event = request.get_json()
    if event.get("type") == "payment.failed":
        return _handle_payment_failed(event)
    return "", 204


def _handle_payment_failed(event):
    data = event.get("data") or {}
    invoice_id = data.get("invoice_id")
    charge_id = data.get("charge_id")
    if not invoice_id or not charge_id:
        return errors.problem(400, "Malformed event", "payment.failed needs data.invoice_id and data.charge_id")

    # The PSP redelivers webhooks; keying on the failed charge drops the duplicates.
    queue.enqueue(
        "dunning.schedule_retries",
        {"invoice_id": invoice_id},
        dedupe_key=f"dunning:{invoice_id}:{charge_id}",
    )
    log.info("payment_failed_retries_enqueued", invoice_id=invoice_id, charge_id=charge_id)
    return "", 204
